package com.vandorlabs.neoforge.reservoir.client;
import com.vandorlabs.neoforge.ModernFinishCatalog;import com.vandorlabs.neoforge.reservoir.*;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.renderer.texture.*;import net.minecraft.core.Direction;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import net.neoforged.neoforge.client.extensions.common.IClientFluidTypeExtensions;
/** Authored Source shell templates, with live charge and per-cell fluid levels. */
public final class NativeBufferRenderer<T extends NativeBufferEntity> implements BlockEntityRenderer<T> {
 static final BatteryGeometryCache BATTERY=new BatteryGeometryCache();static final HexTankGeometryCache TANK=new HexTankGeometryCache(NativeHexTankEntity.CAPACITY);
 private static final ResourceLocation ATLAS=TextureAtlas.LOCATION_BLOCKS;
 public NativeBufferRenderer(BlockEntityRendererProvider.Context context){}
 private static final java.util.Map<String,TextureAtlasSprite> SPRITES=new java.util.LinkedHashMap<>(32,.75F,true);
 private static TextureAtlasSprite sprite(String name){var found=SPRITES.get(name);if(found!=null)return found;found=Minecraft.getInstance().getTextureAtlas(ATLAS).apply(ResourceLocation.parse(name));if(SPRITES.size()>=256)SPRITES.remove(SPRITES.keySet().iterator().next());SPRITES.put(name,found);return found;}
 private static TextureAtlasSprite casing(NativeBufferEntity tile){return tile.casing()==-1?sprite("vandorlabs:blocks/matter/casing"):sprite(ModernFinishCatalog.option(tile.casing()).texture());}
 private static int axis(Direction facing){return facing.getAxis()==Direction.Axis.X?0:facing.getAxis()==Direction.Axis.Z?2:1;}
 private static final class Sink implements BatteryGeometryCache.Sink,HexTankGeometryCache.Sink {
  final PoseStack.Pose pose;VertexConsumer buffer;final TextureAtlasSprite[] textures;final int light,overlay;TextureAtlasSprite current;float nx,ny,nz,r=1,g=1,b=1;int material;Direction portFacing;TextureAtlasSprite outlet;
  Sink(PoseStack.Pose pose,VertexConsumer buffer,TextureAtlasSprite[] textures,int light,int overlay){this.pose=pose;this.buffer=buffer;this.textures=textures;this.light=light;this.overlay=overlay;}
  public void beginQuad(int material,float nx,float ny,float nz){beginQuad(material,0xffffff,true,nx,ny,nz);}
  public void beginQuad(int material,int color,boolean diffuse,float nx,float ny,float nz){this.material=material;current=textures[material];this.nx=nx;this.ny=ny;this.nz=nz;float shade=diffuse?nx*nx*.6F+ny*ny*(ny>0?1:.5F)+nz*nz*.8F:1;r=(color>>16&255)/255F*shade;g=(color>>8&255)/255F*shade;b=(color&255)/255F*shade;}
  Sink ports(Direction facing,TextureAtlasSprite out){portFacing=facing;outlet=out;return this;}
  public void vertex(double x,double y,double z,double u,double v){if(outlet!=null&&material==HexTankGeometryCache.PORT){double coordinate=portFacing.getAxis()==Direction.Axis.X?x:portFacing.getAxis()==Direction.Axis.Y?y:z;current=(coordinate>.5)==(portFacing.getAxisDirection()==Direction.AxisDirection.POSITIVE)?textures[material]:outlet;}buffer.addVertex(pose.pose(),(float)x,(float)y,(float)z).setColor(r,g,b,1).setUv(current.getU((float)u/16),current.getV((float)v/16)).setOverlay(overlay).setLight(light).setNormal(pose,nx,ny,nz);}
 }
 @Override public void render(T tile,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){if(tile instanceof NativeBatteryEntity battery)battery(battery,pose,buffers,light,overlay);else if(tile instanceof NativeHexTankEntity tank)tank(tank,pose,buffers,light,overlay);}
 private static final String[] POWER_ART={"vandorlabs:blocks/resource_ports/power_in_off","vandorlabs:blocks/resource_ports/power_in_on","vandorlabs:blocks/resource_ports/power_out_off","vandorlabs:blocks/resource_ports/power_out_on"};
 private static final class BatterySink implements BatteryGeometryCache.Sink {
  final NativeBatteryEntity owner;final Sink mesh,bars;final com.vandorlabs.ports.BatteryChargeBars.Sink barSink;final double[] corners=new double[12];int index;boolean rectangular,disabled;float nx,ny,nz;
  BatterySink(NativeBatteryEntity owner,PoseStack.Pose pose,VertexConsumer buffer,int light,int overlay){this.owner=owner;var housing=owner.casing()<0?sprite("vandorlabs:blocks/imported/power/battery_cell_bank"):casing(owner);mesh=new Sink(pose,buffer,new TextureAtlasSprite[]{housing,sprite(POWER_ART[0]),sprite(POWER_ART[1]),sprite(POWER_ART[2]),sprite(POWER_ART[3])},light,overlay);bars=new Sink(pose,buffer,new TextureAtlasSprite[]{sprite("vandorlabs:blocks/reservoir/white")},light,overlay);barSink=new com.vandorlabs.ports.BatteryChargeBars.Sink(){public void beginQuad(int color,float nx,float ny,float nz){bars.beginQuad(0,color,true,nx,ny,nz);}public void vertex(double x,double y,double z){bars.vertex(x,y,z,0,0);}};}
  public void beginQuad(int material,float nx,float ny,float nz){this.nx=nx;this.ny=ny;this.nz=nz;index=0;rectangular=material<2;int side=Direction.getNearest(nx,ny,nz).get3DDataValue();var mode=owner.portSettings().face(side);disabled=mode==com.vandorlabs.ports.ResourcePortSettings.Face.DISABLED;int selected=disabled?0:mode==com.vandorlabs.ports.ResourcePortSettings.Face.INPUT?1:3;if(!disabled&&(owner.appearanceMask()&(1<<side))!=0)selected++;mesh.beginQuad(selected,nx,ny,nz);}
  public void vertex(double x,double y,double z,double u,double v){corners[index*3]=x;corners[index*3+1]=y;corners[index*3+2]=z;mesh.vertex(x,y,z,com.vandorlabs.ports.BatteryChargeBars.tiledSideU(u,rectangular&&!disabled&&!owner.blockShape()),v);if(++index==4&&rectangular&&disabled)com.vandorlabs.ports.BatteryChargeBars.emit(corners,nx,ny,nz,owner.amount()/(double)owner.capacity(),barSink);}
 }
 private static void battery(NativeBatteryEntity owner,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var buffer=buffers.getBuffer(RenderType.entityCutoutNoCull(ATLAS));BATTERY.mesh(owner.blockShape(),axis(owner.facing()),owner.facing().getAxisDirection()==Direction.AxisDirection.POSITIVE).emit(new BatterySink(owner,pose.last(),buffer,light,overlay));}
 private static void tank(NativeHexTankEntity tile,PoseStack pose,MultiBufferSource buffers,int light,int overlay){var part=NativeTankGroups.part(tile);if(part.x!=0||part.y!=0)return;pose.pushPose();try{switch(tile.facing().getAxis()){case X->pose.scale(1,part.size,part.size);case Y->pose.scale(part.size,1,part.size);case Z->pose.scale(part.size,part.size,1);}var textures=new TextureAtlasSprite[]{casing(tile),sprite("vandorlabs:blocks/matter/tank_empty"),sprite("vandorlabs:blocks/resource_ports/fluid_in_off"),sprite("minecraft:block/glass")};var geometry=TANK.template(tile.blockShape(),axis(tile.facing()),tile.settings().layout==1,part.size);geometry.shell.emit(new Sink(pose.last(),buffers.getBuffer(RenderType.entityCutoutNoCull(ATLAS)),textures,light,overlay).ports(tile.facing(),sprite("vandorlabs:blocks/resource_ports/fluid_out_off")));var fluid=tile.visibleFluid();int total=fluid.getAmount();if(tile.getLevel()!=null){total=0;var root=tile.getBlockPos();var a=tile.facing().getAxis();for(int x=0;x<part.size;x++)for(int y=0;y<part.size;y++)if(tile.getLevel().getBlockEntity(root.relative(NativeTankGroups.right(a),x).relative(NativeTankGroups.up(a),y)) instanceof NativeHexTankEntity cell){var stored=cell.visibleFluid();total+=stored.getAmount();if(fluid.isEmpty()&&!stored.isEmpty())fluid=stored;}}int amount=total/(part.size*part.size);if(!fluid.isEmpty()&&amount>0){var extension=IClientFluidTypeExtensions.of(fluid.getFluid());var still=extension.getStillTexture(fluid);var water=Minecraft.getInstance().getTextureAtlas(ATLAS).apply(still==null?MissingTextureAtlasSprite.getLocation():still);int color=extension.getTintColor(fluid);var sink=new Sink(pose.last(),buffers.getBuffer(RenderType.entityTranslucent(ATLAS)),new TextureAtlasSprite[]{water},light,overlay);sink.beginQuad(0,color,false,0,1,0);var outline=tile.facing().getAxis()==Direction.Axis.Y?HexTankGeometryCache.fullOutline(tile.blockShape()):TANK.fluidOutline(tile.blockShape(),amount);double high=tile.facing().getAxis()==Direction.Axis.Y?.04+.92*Math.min(1,amount/(double)NativeHexTankEntity.CAPACITY):.96;for(int edge=0;edge<outline.size();edge++){int next=(edge+1)%outline.size();point(sink,outline.x(edge),high,outline.z(edge),tile.facing(),0,0);point(sink,outline.x(edge),.0405,outline.z(edge),tile.facing(),0,16);point(sink,outline.x(next),.0405,outline.z(next),tile.facing(),16,16);point(sink,outline.x(next),high,outline.z(next),tile.facing(),16,0);}cap(sink,outline,high,tile.facing());cap(sink,outline,.0405,tile.facing());}geometry.windows.emit(new Sink(pose.last(),buffers.getBuffer(RenderType.entityTranslucent(ATLAS)),textures,light,overlay));}finally{pose.popPose();}}
 private static void point(Sink sink,double x,double y,double z,Direction face,double u,double v){x=.5+(x-.5)*.895;z=.5+(z-.5)*.895;switch(face.getAxis()){case X->sink.vertex(y,z,x,u,v);case Y->sink.vertex(x,y,z,u,v);case Z->sink.vertex(x,z,y,u,v);}}
 private static void cap(Sink sink,HexTankGeometryCache.Outline outline,double y,Direction face){double cx=0,cz=0;for(int i=0;i<outline.size();i++){cx+=outline.x(i);cz+=outline.z(i);}cx/=outline.size();cz/=outline.size();for(int i=0;i<outline.size();i++){int n=(i+1)%outline.size();point(sink,cx,y,cz,face,cx*16,cz*16);point(sink,outline.x(i),y,outline.z(i),face,outline.x(i)*16,outline.z(i)*16);point(sink,outline.x(n),y,outline.z(n),face,outline.x(n)*16,outline.z(n)*16);point(sink,cx,y,cz,face,cx*16,cz*16);}}
 @Override public AABB getRenderBoundingBox(T tile){return new AABB(tile.getBlockPos()).inflate(3);}
 static void clear(){BATTERY.clear();TANK.clear();SPRITES.clear();}
}
